import React, { useState } from "react";
import { Plus } from "lucide-react";
import StatCard from "../components/StatCard";
import ProgressBar from "../components/ProgressBar";
import StatusBadge from "../components/StatusBadge";
import ExpenseTrendChart from "../components/ExpenseTrendChart";
import QuickAddModal from "../components/QuickAddModal";
import { TRANSACTIONS, BUDGETS, MONTHLY_DATA } from "../data/mockData";

const CATEGORY_ICONS: Record<string, string> = {
  Income: "💰",
  Food: "🛒",
  Housing: "🏠",
  Entertainment: "🎬",
  Transport: "🚗",
  Shopping: "🛍️",
  Health: "💊",
};

const Dashboard: React.FC = () => {
  const [showQuickAdd, setShowQuickAdd] = useState(false);

  return (
    <div className="p-4 md:p-6 max-w-6xl mx-auto">
      {/* Page header */}
      <div className="flex items-start justify-between mb-5">
        <div>
          <h1 className="text-xl font-medium text-gray-900">Dashboard</h1>
          <p className="text-sm text-gray-400 mt-0.5">Welcome back, Alex — June 2024</p>
        </div>
        <button
          onClick={() => setShowQuickAdd((v) => !v)}
          className="flex items-center gap-2 px-4 py-2 bg-emerald-500 hover:bg-emerald-600 text-white text-sm font-medium rounded-lg transition-colors"
        >
          <Plus size={16} />
          Quick Add
        </button>
      </div>

      {showQuickAdd && <QuickAddModal onClose={() => setShowQuickAdd(false)} />}

      {/* Stat cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-5">
        <StatCard label="Total Balance" value="$12,450" change="3.2% vs last month" trend="up" />
        <StatCard label="Total Income" value="$6,000" change="8.1% this month" trend="up" valueColor="green" />
        <StatCard label="Total Expenses" value="$3,800" change="2.4% vs avg" trend="down" valueColor="red" />
        <StatCard label="Monthly Savings" value="$2,200" change="12.5% increase" trend="up" valueColor="blue" />
      </div>

      {/* Charts row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 mb-4">
        {/* Expense Trend */}
        <div className="lg:col-span-2 bg-white border border-gray-100 rounded-xl p-5">
          <h2 className="text-sm font-medium text-gray-700 mb-4">Expense Trend</h2>
          <ExpenseTrendChart data={MONTHLY_DATA} />
        </div>

        {/* Budget Status */}
        <div className="bg-white border border-gray-100 rounded-xl p-5">
          <h2 className="text-sm font-medium text-gray-700 mb-4">Budget Status</h2>
          <div className="flex flex-col gap-4">
            {BUDGETS.map((budget, i) => {
              const pct = Math.round((budget.spent / budget.limit) * 100);
              const over = pct > 100;
              return (
                <div key={i}>
                  <div className="flex justify-between items-center mb-1.5 text-sm">
                    <div className="flex items-center gap-2">
                      <span
                        className="w-2 h-2 rounded-full"
                        style={{ background: budget.color }}
                      />
                      <span className="text-gray-700">{budget.category}</span>
                    </div>
                    <span className={over ? "text-red-500 text-xs" : "text-gray-400 text-xs"}>
                      ${budget.spent}/${budget.limit}
                    </span>
                  </div>
                  <ProgressBar
                    value={pct}
                    color={budget.color}
                    overBudget={over}
                  />
                  {over && (
                    <p className="text-xs text-red-500 mt-1">
                      ⚠ Over by ${budget.spent - budget.limit}
                    </p>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* Recent transactions */}
      <div className="bg-white border border-gray-100 rounded-xl p-5">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-sm font-medium text-gray-700">Recent Transactions</h2>
          <span className="text-xs text-emerald-600 cursor-pointer hover:underline">
            View all →
          </span>
        </div>
        <div className="divide-y divide-gray-50">
          {TRANSACTIONS.slice(0, 6).map((tx) => (
            <div key={tx.id} className="flex items-center gap-3 py-3">
              <div
                className={`w-9 h-9 rounded-lg flex items-center justify-center text-lg shrink-0 ${
                  tx.amount > 0 ? "bg-emerald-50" : "bg-red-50"
                }`}
              >
                {CATEGORY_ICONS[tx.category] ?? "💳"}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-gray-800 truncate">{tx.description}</p>
                <p className="text-xs text-gray-400">
                  {tx.category} · {tx.date}
                </p>
              </div>
              <StatusBadge status={tx.status} />
              <span
                className={`text-sm font-medium shrink-0 ${
                  tx.amount > 0 ? "text-emerald-600" : "text-red-500"
                }`}
              >
                {tx.amount > 0 ? "+" : "-"}${Math.abs(tx.amount).toFixed(2)}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
